public class ThumbnailScalerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        if (x < 0 || y < 0 || x >= img.getWidth() || y >= img.getHeight()) {
            return "out-of-range";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static int widthOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getWidth();
    }

    static int heightOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getHeight();
    }

    static java.awt.image.BufferedImage ramp(int w, int h) {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                w, h, java.awt.image.BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int r = (x * 40 + 15) % 256;
                int gr = (y * 40 + 15) % 256;
                int b = (x * 17 + y * 5 + 3) % 256;
                img.setRGB(x, y, (r << 16) | (gr << 8) | b);
            }
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src4 = ramp(4, 4);
            java.awt.image.BufferedImage small = ThumbnailScaler.shrink(src4, 2, 2);
            java.awt.image.BufferedImage src6 = ramp(6, 6);
            java.awt.image.BufferedImage four = ThumbnailScaler.shrink(src6, 4, 4);
            check("thumbnail width", 2, widthOf(small));
            check("thumbnail height", 2, heightOf(small));
            check("thumbnail (0,0) samples source (0,0)", "#0F0F03", pixel(small, 0, 0));
            check("thumbnail (1,0) samples source (2,0)", "#5F0F25", pixel(small, 1, 0));
            check("thumbnail (1,1) samples source (2,2)", "#5F5F2F", pixel(small, 1, 1));
            check("source is untouched at (1,1)", "#373719", pixel(src4, 1, 1));
            check("6x6 down to 4x4 at (3,3)", "#AFAF5B", pixel(four, 3, 3));
            check("6x6 down to 4x4 at (1,2)", "#378723", pixel(four, 1, 2));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

