import java.awt.image.BufferedImage;

public class ThumbnailScaler {

    public static BufferedImage shrink(BufferedImage src, int newWidth, int newHeight) {
        BufferedImage out = new BufferedImage(newWidth, newHeight, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < newHeight; y++) {
            for (int x = 0; x < newWidth; x++) {
                int srcX = x * src.getWidth() / newWidth;
                int srcY = y * src.getHeight() / newHeight;
                out.setRGB(x, y, src.getRGB(srcX, srcY));
            }
        }
        return out;
    }
}
